CREATE TYPE "RewardType" AS ENUM ('virtual', 'physical'); CREATE TYPE "RewardClaimStatus" AS ENUM ('pending', 'accepted', 'declined', 'fulfilled'); ALTER TABLE "users" ADD COLUMN "is_admin" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "rewards" ("id" UUID NOT NULL, "name" VARCHAR(160) NOT NULL, "description" TEXT NOT NULL, "reward_type" "RewardType" NOT NULL, "image_url" TEXT, "inventory" INTEGER, "active" BOOLEAN NOT NULL DEFAULT true, "config" JSONB NOT NULL DEFAULT '{}', "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "rewards_pkey" PRIMARY KEY ("id")); CREATE INDEX "rewards_active_created_at_idx" ON "rewards"("active", "created_at");
CREATE TABLE "reward_claims" ("id" UUID NOT NULL, "reward_id" UUID NOT NULL, "user_id" UUID NOT NULL, "status" "RewardClaimStatus" NOT NULL DEFAULT 'pending', "accepted_at" TIMESTAMP(3), "fulfilled_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "reward_claims_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "reward_claims_reward_id_user_id_key" ON "reward_claims"("reward_id", "user_id"); CREATE INDEX "reward_claims_user_id_status_idx" ON "reward_claims"("user_id", "status");
CREATE TABLE "reward_addresses" ("id" UUID NOT NULL, "user_id" UUID NOT NULL, "encrypted_value" TEXT NOT NULL, "value_hash" CHAR(64) NOT NULL, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "reward_addresses_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "reward_addresses_user_id_key" ON "reward_addresses"("user_id");
CREATE TABLE "reward_audits" ("id" UUID NOT NULL, "actor_id" UUID NOT NULL, "claim_id" UUID, "action" VARCHAR(80) NOT NULL, "target_hash" CHAR(64), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "reward_audits_pkey" PRIMARY KEY ("id")); CREATE INDEX "reward_audits_claim_id_created_at_idx" ON "reward_audits"("claim_id", "created_at");
ALTER TABLE "reward_claims" ADD CONSTRAINT "reward_claims_reward_id_fkey" FOREIGN KEY ("reward_id") REFERENCES "rewards"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "reward_claims" ADD CONSTRAINT "reward_claims_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "reward_addresses" ADD CONSTRAINT "reward_addresses_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "reward_audits" ADD CONSTRAINT "reward_audits_actor_id_fkey" FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
